MULT = {'requirements': 1, 'design': 5, 'implementation': 20, 'testing': 50, 'production': 100}

def late_cost(base_hours):
    costs = {}
    for phase in MULT:
        costs[phase] = base_hours * MULT[phase]
        print('caught in %s cost: %dh' % (phase, costs[phase]))
    ratio = costs['production'] // costs['requirements']
    print('production vs requirements: %dx' % ratio)
    return costs

result = late_cost(2)
